<?php
require_once __DIR__.'/page-guides.php';
function field(string $name,string $label,string $type='text',bool $required=true,string $value=''): void {
 echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required ':'').'maxlength="'.($name==='message'?4000:190).'"';
 if($type==='date')echo ' min="'.date('Y-m-d').'"';if($type==='number')echo ' min="'.($name==='children'?0:1).'" max="500" step="1"';if($name==='name'||$name==='full_name')echo ' autocomplete="name"';if($name==='mobile')echo ' autocomplete="tel"';if($name==='email')echo ' autocomplete="email"';echo '></label>';
}
function package_card(array $p): void { $m=media_for('packages',(int)$p['id']);echo '<article class="card tilt">'.picture($m[0]??null).'<div class="card-body"><span class="eyebrow">'.e($p['category']).' · '.e($p['trip_type']).'</span><h3>'.e($p['name']).'</h3><p>'.e($p['destination']).' · '.e(duration($p)).'</p><p class="price">'.($p['starting_price']!==null?e($p['currency']).' '.number_format((float)$p['starting_price'],2).' <small>starting price</small>':'Request Quote').'</p><div class="actions"><a class="button secondary" href="'.e(url('package/'.$p['slug'])).'">View Details</a>'.booking_button(package_message($p)).'</div></div></article>'; }
function package_grid(array $packages): void { echo '<div class="grid">';foreach($packages as $p)package_card($p);if(!$packages)echo '<div class="empty"><h3>Your next journey is taking shape.</h3><p>Approved packages will appear here. Tell us where you would like to travel.</p><a class="text-link" href="'.e(url('contact')).'">Make an enquiry →</a></div>';echo '</div>'; }
function service_card(array $s): void { $m=media_for('services',(int)$s['id']);echo '<article class="card"><div class="card-body"><span class="service-icon" aria-hidden="true">✦</span><h3>'.e($s['name']).'</h3>'.text_block($s['description']);if($m)echo picture($m[0]);echo booking_button("Hello The Dream Holidays!\nI would like to enquire about ".$s['name'].".\nPlease share availability, details and a quotation.").'</div></article>'; }
function vehicle_card(array $v): void { $m=media_for('vehicles',(int)$v['id']);echo '<article class="card">'.picture($m[0]??null).'<div class="card-body"><span class="eyebrow">'.e($v['category']).'</span><h3>'.e($v['name']).'</h3><p>'.e($v['seating']).' passengers · '.e($v['air_conditioning']).'</p>';foreach(['luggage'=>'Luggage','amenities'=>'Confirmed amenities','rental_terms'=>'Rental terms'] as $key=>$label)if($v[$key]!=='')echo '<h4>'.e($label).'</h4>'.text_block($v[$key]);echo '<form method="post" action="'.e(url('vehicle-booking')).'" class="vehicle-booking" data-number="'.e(setting('whatsapp_number')).'" data-name="'.e($v['name']).'" data-category="'.e($v['category']).'" data-seating="'.e($v['seating']).'" data-ac="'.e($v['air_conditioning']).'">'.csrf_field().'<input type="hidden" name="vehicle_id" value="'.e($v['id']).'">';field('travel_date','Travel date','date',false);field('pickup','Pickup location','text',false);field('travellers','Travellers','number',false);echo '<button class="button booking" type="submit" '.(!phone_valid(setting('whatsapp_number'))?'disabled':'').'>Booking</button><p class="help">Our team will confirm vehicle availability and rental terms.</p>';if(!phone_valid(setting('whatsapp_number')))echo contact_alternative();echo '</form></div></article>'; }
function enquiry_form(): void {
 $key=bin2hex(random_bytes(32));if(count($_SESSION['enquiry_tokens']??[])>=100)array_shift($_SESSION['enquiry_tokens']);$_SESSION['enquiry_tokens'][$key]=time();foreach($_SESSION['enquiry_tokens']??[] as $k=>$time)if(time()-$time>7200)unset($_SESSION['enquiry_tokens'][$k]);
 $old=$_SESSION['enquiry_old']??[];unset($_SESSION['enquiry_old']);
 echo '<form action="'.e(url('enquiry')).'" method="post" class="enquiry-form"><div class="form-grid">'.csrf_field().'<input type="hidden" name="submission_key" value="'.e($key).'"><div class="honeypot" aria-hidden="true"><label>Leave this empty<input name="website" tabindex="-1" autocomplete="off"></label></div>';
 foreach([['full_name','Full name','text',true],['mobile','Mobile number','tel',true],['email','Email','email',false],['interest','Destination, package or service','text',true],['departure_city','Departure city','text',true],['travel_date','Travel date','date',true],['adults','Adults','number',true],['children','Children','number',true],['vehicle_preference','Vehicle preference','text',false]] as [$n,$l,$t,$r])field($n,$l,$t,$r,(string)($old[$n]??($n==='children'?'0':'')));
 echo '<label class="full">Message (optional)<textarea name="message" maxlength="4000" rows="4">'.e($old['message']??'').'</textarea></label></div><button class="button" type="submit">Send Enquiry</button><p class="help">Submitting an enquiry does not confirm a booking. Our team will discuss availability and quotation with you.</p><p class="help">Your submitted details are stored to respond to this enquiry. Please avoid including sensitive documents or payment information.</p></form>';
}
function contact_details(): void {
 echo '<div class="contact-details">';$p=setting('phone');$email=setting('email');
 if(preg_match('/^\+?[0-9 ()-]{8,25}$/D',$p))echo '<p><span class="eyebrow">Call</span><br><a href="tel:'.e(preg_replace('/[^+0-9]/','',$p)).'">'.e($p).'</a></p>';
 if(filter_var($email,FILTER_VALIDATE_EMAIL))echo '<p><span class="eyebrow">Email</span><br><a href="mailto:'.e($email).'">'.e($email).'</a></p>';
 foreach(['address'=>'Visit','hours'=>'Working hours'] as $k=>$l)if(setting($k)!=='')echo '<p><span class="eyebrow">'.e($l).'</span><br>'.nl2br(e(setting($k))).'</p>';
 if(!$p&&!$email&&!setting('address'))echo '<p>Business contact information is awaiting approval. You can submit a website enquiry below.</p>';
 foreach(['instagram','facebook','youtube'] as $key){$link=setting($key);if(filter_var($link,FILTER_VALIDATE_URL)&&str_starts_with($link,'https://'))echo '<a class="social-link" href="'.e($link).'" target="_blank" rel="noopener noreferrer">'.ucfirst($key).'</a>';}
 $map=setting('maps_embed_url');if(preg_match('~^https://(?:www\.google\.com/maps/embed|maps\.google\.com/maps)(?:\?|/)~',$map))echo '<iframe class="map" src="'.e($map).'" title="The Dream Holidays location" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe>';echo '</div>';
}
if($route==='vehicle-booking'){
 if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit;}
 check_csrf();$vehicle=one("SELECT * FROM vehicles WHERE id=? AND status='published'",[(int)($_POST['vehicle_id']??0)]);
 if(!$vehicle)throw new HttpError('This vehicle listing is unavailable.',404);
 $lines=['Hello The Dream Holidays!','I would like to book a vehicle.','','Vehicle: '.$vehicle['name'],'Category: '.$vehicle['category'],'Seating: '.$vehicle['seating'].' passengers','Air conditioning: '.$vehicle['air_conditioning']];
 foreach(['travel_date'=>'Travel Date','pickup'=>'Pickup Location','travellers'=>'Travellers'] as $key=>$label){$value=trim((string)($_POST[$key]??''));if($value==='')continue;if(strlen($value)>190)throw new HttpError('Vehicle enquiry details are too long.',422);if($key==='travel_date'){$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$date||$date->format('Y-m-d')!==$value||$value<date('Y-m-d'))throw new HttpError('Choose today or a future travel date.',422);}if($key==='travellers'&&filter_var($value,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>500]])===false)throw new HttpError('Provide a valid traveller count.',422);$lines[]=$label.': '.$value;}
 $lines[]='';$lines[]='Please confirm availability, rental terms and share the quotation.';$wa=whatsapp(implode("\n",$lines));if(!$wa){flash('Booking contact information is unavailable. Please use the website enquiry form.');redirect('contact');}header('Location: '.$wa,true,303);exit;
}
$errorList=[];$p=null;$page=null;
if($route==='enquiry'){
 header('Cache-Control: no-store');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit;}
 check_csrf();$key=(string)($_POST['submission_key']??'');
 if(!preg_match('/^[a-f0-9]{64}$/D',$key)||!isset($_SESSION['enquiry_tokens'][$key])){flash('This form has expired. Please submit a fresh form.');redirect('contact');}
 $existing=one('SELECT reference FROM enquiries WHERE submission_key=?',[$key]);if($existing){flash('Your enquiry was already stored. Reference: '.$existing['reference']);redirect('contact');}
 [$data,$errorList]=validated_travel($_POST,true);
 if(!empty($_POST['website'])||time()-$_SESSION['enquiry_tokens'][$key]<2)$errorList[]='Please wait a moment and try again.';
 if(!rate_limit('enquiry',8,900))$errorList[]='Too many submissions. Please try again later.';
 if($errorList){$_SESSION['enquiry_old']=$data;flash(implode(' ',$errorList));redirect('contact');}
 $reference='TDH-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(5)));
 try{db()->beginTransaction();query('INSERT INTO enquiries(reference,submission_key,full_name,mobile,email,interest,departure_city,travel_date,adults,children,vehicle_preference,message) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$reference,$key,$data['full_name'],$data['mobile'],$data['email']?:null,$data['interest'],$data['departure_city'],$data['travel_date'],(int)$data['adults'],(int)$data['children'],$data['vehicle_preference']?:null,$data['message']?:null]);db()->commit();flash('Your enquiry has been saved. Reference: '.$reference.'. This is not a booking confirmation.');}
 catch(Throwable $error){if(db()->inTransaction())db()->rollBack();$stored=one('SELECT reference FROM enquiries WHERE submission_key=?',[$key]);if($stored)flash('Your enquiry was already stored. Reference: '.$stored['reference']);else{error_log((string)$error);$_SESSION['enquiry_old']=$data;flash('We could not save your enquiry. Please try again.');}}
 redirect('contact');
}
