iv><?php endif?><form method="post" class="package-booking" action="<?=e(url('package/'.$p['slug']))?>" data-number="<?=e(setting('whatsapp_number'))?>" data-name="<?=e($p['name'])?>" data-duration="<?=e(duration($p))?>" data-link="<?=e(url('package/'.$p['slug']))?>"><?php if(!empty($isAdminPreview)):?><fieldset disabled class="preview-booking-fields"><?php endif?><?=csrf_field()?><?php foreach([['name','Customer name','text'],['departure_city','Departure city','text'],['travel_date','Travel date','date'],['adults','Adults','number'],['children','Children','number']] as [$n,$l,$t])field($n,$l,$t,true,(string)($_POST[$n]??($n==='children'?'0':'')));?><label>Message (optional)<textarea name="message" rows="3" maxlength="4000"><?=e($_POST['message']??'')?></textarea></label><button class="button booking" <?=!phone_valid(setting('whatsapp_number'))?'disabled':''?>>Booking</button><p class="help">You will review and send the message in your chat. Opening the chat does not confirm a booking.</p><?php if(!phone_valid(setting('whatsapp_number')))echo contact_alternative();if(!empty($isAdminPreview))echo '</fieldset>';?></form></aside></section><div class="mobile-sticky"><?php if(empty($isAdminPreview)&&phone_valid(setting('whatsapp_number'))):?><a class="button booking" href="#booking">Booking</a><?php else:?><button class="button booking" disabled>Booking</button><?php endif?><?php if(preg_match('/^\+?[0-9 ()-]{8,25}$/D',setting('phone'))):?><a class="button secondary" href="tel:<?=e(preg_replace('/[^+0-9]/','',setting('phone')))?>">Call</a><?php endif?></div>
<?php elseif($route==='services'||$route==='vehicles'):?><section class="page-heading container"><span class="eyebrow"><?=$route==='services'?'TRAVEL YOUR WAY':'ON THE ROAD'?></span><h1><?=$route==='services'?'Journeys for every occasion.':'A comfortable ride awaits.'?></h1><p><?=$route==='services'?'Explore our business-approved travel services.':'Browse vehicle specifications and request a quotation. Availability is confirmed by our team.'?></p></section><?php page_guide_intro($route);?><section class="section-top container"><div class="grid"><?php $records=rows('SELECT * FROM '.$route." WHERE status='published' ORDER BY id");foreach($records as $record){if($route==='services')service_card($record);else vehicle_card($record);}if(!$records)echo '<p class="empty">Approved '.e($route).' will appear here. <a href="'.e(url('contact')).'">Send an enquiry</a> to discuss your needs.</p>';?></div></section>
<?php elseif($route==='gallery'):?><section class="page-heading container"><span class="eyebrow">A WINDOW INTO OUR JOURNEYS</span><h1>Places. People. Possibilities.</h1><p>Business-approved photographs from trips, destinations and vehicles.</p></section><?php page_guide_intro($route);?><section class="section-top container"><form class="filters" method="get" action="<?=e(url('gallery'))?>"><input type="hidden" name="route" value="gallery"><label>Category<select name="category"><option value="">All categories</option><?php foreach(rows('SELECT * FROM gallery_categories ORDER BY name') as $cat):?><option value="<?=e($cat['id'])?>" <?=($_GET['category']??'')===(string)$cat['id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach?></select></label><button class="button">Filter Gallery</button></form><div class="gallery-grid"><?php $args=[];$sql="SELECT * FROM media WHERE owner_type='gallery' AND status='published'";if(!empty($_GET['category'])){$sql.=' AND gallery_category_id=?';$args[]=(int)$_GET['category'];}$images=rows($sql.' ORDER BY sort_order,id',$args);foreach($images as $m)echo '<figure><button class="gallery-open" data-src="'.e(asset('media/'.$m['filename'])).'" data-alt="'.e($m['alt_text']).'">'.picture($m).'</button><figcaption>'.e($m['alt_text']).($m['credit']?' · '.e($m['credit']):'').'</figcaption></figure>';if(!$images)echo '<p class="empty">Approved photographs will appear here.</p>';?></div></section>
<?php elseif($route==='contact'):if(!isset($_SESSION['enquiry_old'])&&isset($_GET['interest']))$_SESSION['enquiry_old']=['interest'=>substr((string)$_GET['interest'],0,190)];?><section class="page-heading container"><span class="eyebrow">LET’S TALK TRAVEL</span><h1>Start with a hello.</h1><p>Share your ideas. We’ll help you plan the next step.</p></section><?php page_guide_intro($route);?><section class="container contact-grid section-top"><div><?php contact_details();?></div><div id="enquiry"><h2>Send a website enquiry</h2><?php enquiry_form();?></div></section>
<?php elseif($page&&$page['slug']==='about'):require __DIR__.'/about.php';?><?php elseif($page):?><section class="page-heading container"><span class="eyebrow">THE DREAM HOLIDAYS</span><h1><?=e($page['title'])?></h1></section><section class="container reading section-top"><?=text_block($page['body'])?><?php if($page['slug']==='about'):foreach(['travel_approach'=>'Our travel approach','team'=>'Our team','service_locations'=>'Service locations'] as $key=>$label)if(setting($key)!=='')echo '<h2>'.e($label).'</h2>'.text_block(setting($key));endif?></section>
<?php else:?><section class="page-heading container"><h1>This page is not available.</h1><p>The content may still be awaiting approval.</p><a class="button" href="<?=e(url())?>">Back to Home</a></section><?php endif?>
<?php if(in_array($route,['packages','services','vehicles','gallery','contact'],true))page_guide_end($route);?></main><footer class="site-footer"><div class="container footer-grid"><div><a class="brand" href="<?=e(url())?>"><?=brand_markup()?></a><p>Thoughtfully planned tours.<br>Journeys worth remembering.</p></div><div><h3>Explore</h3><a href="<?=e(url('packages'))?>">Tour packages</a><a href="<?=e(url('vehicles'))?>">Vehicle rentals</a><a href="<?=e(url('contact'))?>">Contact & enquiries</a></div><div><h3>Information</h3><a href="<?=e(url('about'))?>">About Us</a><a href="<?=e(url('services'))?>">Travel services</a><a href="<?=e(url('gallery'))?>">Travel gallery</a><?php foreach(rows("SELECT slug,title FROM pages WHERE status='published' AND slug NOT IN ('about','services','gallery') ORDER BY id") as $pg):?><a href="<?=e(url($pg['slug']))?>"><?=e($pg['title'])?></a><?php endforeach?></div><div><h3>Plan your next chapter.</h3><a class="button" href="<?=e(url('contact'))?>">Get a Quote →</a></div></div><div class="container footer-bottom">© <?=date('Y')?> The Dream Holidays. <span>Availability and bookings are confirmed by our team.</span></div></footer>
